<template><div v-loading="loading"><div class="section"><div class="section-header"><div><h2 class="section-title">Kimi 能力测试结果</h2><p class="subtitle">{{ data?.config?.model || 'kimi-k3' }} · {{ statusText }}</p></div><el-button @click="router.push('/tests/kimi-suite')">再次测试</el-button></div><div class="section-body"><el-progress :percentage="progressPercent"/><p>当前 Case：{{ data?.progress?.current_case || '等待开始' }}　场景：{{ data?.progress?.current_scenario || '-' }}</p></div></div><div v-if="summary" class="section"><div class="section-header"><h2 class="section-title">Case 执行摘要</h2></div><div class="section-body"><el-table :data="summary.cases" border><el-table-column prop="case_name" label="Case 名称" min-width="240"/><el-table-column prop="status" label="状态" width="130"/><el-table-column prop="elapsed_sec" label="耗时" width="120"/><el-table-column prop="manual_rerun_count" label="人工重跑" width="110"/><el-table-column label="失败原因" min-width="240"><template #default="scope"><span>{{ scope.row.scenarios?.find(x => x.status !== 'passed')?.assertion?.detail || '-' }}</span></template></el-table-column></el-table><div v-for="item in summary.cases" :key="item.case_id" class="detail"><h3>{{ item.case_name }}</h3><el-descriptions v-for="scenario in item.scenarios" :key="scenario.scenario_id" :column="3" border><el-descriptions-item label="场景">{{ scenario.scenario_name }}</el-descriptions-item><el-descriptions-item label="状态">{{ scenario.status }}</el-descriptions-item><el-descriptions-item label="耗时">{{ Number(scenario.latency_sec || 0).toFixed(3) }}s</el-descriptions-item></el-descriptions></div></div></div></div></template>
<script setup>
import { computed, onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import { ElMessage } from 'element-plus'; import { getKimiSuite } from '../api/client'
const props=defineProps({id:{type:String,required:true}}); const router=useRouter(); const data=ref(null); const loading=ref(false); let timer
const summary=computed(()=>data.value?.summary); const statusText=computed(()=>({queued:'排队中',running:'运行中',completed:'已完成',failed:'失败',cancelled:'已取消'}[data.value?.task_status]||data.value?.task_status||'加载中')); const progressPercent=computed(()=>{const p=data.value?.progress||{}; const total=Number(p.total_cases||summary.value?.results?.total_cases||0); const done=Number(p.completed_cases||summary.value?.results?.passed||0); return total?Math.min(100,Math.round(done/total*100)):summary.value?100:0})
async function load(){try{data.value=await getKimiSuite(props.id);if(!['completed','failed','cancelled','interrupted'].includes(data.value.task_status))timer=setTimeout(load,1500)}catch(e){ElMessage.error(e.message)}finally{loading.value=false}} onMounted(()=>{loading.value=true;load()})
</script>
<style scoped>.detail{margin-top:20px}.detail h3{margin-bottom:8px}</style>
